1	package com.bumptech.glide.load.engine;
2	
3	import android.os.Process;
4	import androidx.annotation.NonNull;
5	import androidx.annotation.Nullable;
6	import androidx.annotation.VisibleForTesting;
7	import com.bumptech.glide.load.Key;
8	import com.bumptech.glide.load.engine.EngineResource.ResourceListener;
9	import com.bumptech.glide.util.Executors;
10	import com.bumptech.glide.util.Preconditions;
11	import com.bumptech.glide.util.Synthetic;
12	import java.lang.ref.ReferenceQueue;
13	import java.lang.ref.WeakReference;
14	import java.util.HashMap;
15	import java.util.Map;
16	import java.util.concurrent.Executor;
17	import java.util.concurrent.ExecutorService;
18	import java.util.concurrent.ThreadFactory;
19	
20	final class ActiveResources {
21	  private final boolean isActiveResourceRetentionAllowed;
22	  private final Executor monitorClearedResourcesExecutor;
23	  @VisibleForTesting final Map<Key, ResourceWeakReference> activeEngineResources = new HashMap<>();
24	  private final ReferenceQueue<EngineResource<?>> resourceReferenceQueue = new ReferenceQueue<>();
25	
26	  private ResourceListener listener;
27	
28	  private volatile boolean isShutdown;
29	  @Nullable private volatile DequeuedResourceCallback cb;
30	
31	  ActiveResources(boolean isActiveResourceRetentionAllowed) {
32	    this(
33	        isActiveResourceRetentionAllowed,
34	        java.util.concurrent.Executors.newSingleThreadExecutor(
35	            new ThreadFactory() {
36	              @Override
37	              public Thread newThread(@NonNull final Runnable r) {
38	                return new Thread(
39	                    new Runnable() {
40	                      @Override
41	                      public void run() {
42	                        Process.setThreadPriority(Process.THREAD_PRIORITY_BACKGROUND);
43	                        r.run();
44	                      }
45	                    },
46	                    "glide-active-resources");
47	              }
48	            }));
49	  }
50	
51	  @VisibleForTesting
52	  ActiveResources(
53	      boolean isActiveResourceRetentionAllowed, Executor monitorClearedResourcesExecutor) {
54	    this.isActiveResourceRetentionAllowed = isActiveResourceRetentionAllowed;
55	    this.monitorClearedResourcesExecutor = monitorClearedResourcesExecutor;
56	
57	    monitorClearedResourcesExecutor.execute(
58	        new Runnable() {
59	          @Override
60	          public void run() {
61	            cleanReferenceQueue();
62	          }
63	        });
64	  }
65	
66	  void setListener(ResourceListener listener) {
67	    synchronized (listener) {
68	      synchronized (this) {
69	        this.listener = listener;
70	      }
71	    }
72	  }
73	
74	  synchronized void activate(Key key, EngineResource<?> resource) {
75	    ResourceWeakReference toPut =
76	        new ResourceWeakReference(
77	            key, resource, resourceReferenceQueue, isActiveResourceRetentionAllowed);
78	
79	    ResourceWeakReference removed = activeEngineResources.put(key, toPut);
80	    if (removed != null) {
81	      removed.reset();
82	    }
83	  }
84	
85	  synchronized void deactivate(Key key) {
86	    ResourceWeakReference removed = activeEngineResources.remove(key);
87	    if (removed != null) {
88	      removed.reset();
89	    }
90	  }
91	
92	  @Nullable
93	  synchronized EngineResource<?> get(Key key) {
94	    ResourceWeakReference activeRef = activeEngineResources.get(key);
95	    if (activeRef == null) {
96	      return null;
97	    }
98	
99	    EngineResource<?> active = activeRef.get();
100	    if (active == null) {
101	      cleanupActiveReference(activeRef);
102	    }
103	    return active;
104	  }
105	
106	  @SuppressWarnings({"WeakerAccess", "SynchronizeOnNonFinalField"})
107	  @Synthetic
108	  void cleanupActiveReference(@NonNull ResourceWeakReference ref) {
109	    synchronized (this) {
110	      activeEngineResources.remove(ref.key);
111	
112	      if (!ref.isCacheable || ref.resource == null) {
113	        return;
114	      }
115	    }
116	
117	    EngineResource<?> newResource =
118	        new EngineResource<>(
119	            ref.resource,
120	            /* isMemoryCacheable= */ true,
121	            /* isRecyclable= */ false,
122	            ref.key,
123	            listener);
124	    listener.onResourceReleased(ref.key, newResource);
125	  }
126	
127	  @SuppressWarnings("WeakerAccess")
128	  @Synthetic
129	  void cleanReferenceQueue() {
130	    while (!isShutdown) {
131	      try {
132	        ResourceWeakReference ref = (ResourceWeakReference) resourceReferenceQueue.remove();
133	        cleanupActiveReference(ref);
134	
135	        // This section for testing only.
136	        DequeuedResourceCallback current = cb;
137	        if (current != null) {
138	          current.onResourceDequeued();
139	        }
140	        // End for testing only.
141	      } catch (InterruptedException e) {
142	        Thread.currentThread().interrupt();
143	      }
144	    }
145	  }
146	
147	  @VisibleForTesting
148	  void setDequeuedResourceCallback(DequeuedResourceCallback cb) {
149	    this.cb = cb;
150	  }
151	
152	  @VisibleForTesting
153	  interface DequeuedResourceCallback {
154	    void onResourceDequeued();
155	  }
156	
157	  @VisibleForTesting
158	  void shutdown() {
159	    isShutdown = true;
160	    if (monitorClearedResourcesExecutor instanceof ExecutorService) {
161	      ExecutorService service = (ExecutorService) monitorClearedResourcesExecutor;
162	      Executors.shutdownAndAwaitTermination(service);
163	    }
164	  }
165	
166	  @VisibleForTesting
167	  static final class ResourceWeakReference extends WeakReference<EngineResource<?>> {
168	    @SuppressWarnings("WeakerAccess")
169	    @Synthetic
170	    final Key key;
171	
172	    @SuppressWarnings("WeakerAccess")
173	    @Synthetic
174	    final boolean isCacheable;
175	
176	    @Nullable
177	    @SuppressWarnings("WeakerAccess")
178	    @Synthetic
179	    Resource<?> resource;
180	
181	    @Synthetic
182	    @SuppressWarnings("WeakerAccess")
183	    ResourceWeakReference(
184	        @NonNull Key key,
185	        @NonNull EngineResource<?> referent,
186	        @NonNull ReferenceQueue<? super EngineResource<?>> queue,
187	        boolean isActiveResourceRetentionAllowed) {
188	      super(referent, queue);
189	      this.key = Preconditions.checkNotNull(key);
190	      this.resource =
191	          referent.isMemoryCacheable() && isActiveResourceRetentionAllowed
192	              ? Preconditions.checkNotNull(referent.getResource())
193	              : null;
194	      isCacheable = referent.isMemoryCacheable();
195	    }
196	
197	    void reset() {
198	      resource = null;
199	      clear();
200	    }
201	  }
202	}
