41	   * present.
42	   */
43	  // Public API.
44	  @SuppressWarnings("WeakerAccess")
45	  public static final int LOOP_INTRINSIC = 0;
46	
47	  private static final int GRAVITY = Gravity.FILL;
48	
49	  private final GifState state;
50	
51	  /** True if the drawable is currently animating. */
52	  private boolean isRunning;
53	
54	  /** True if the drawable should animate while visible. */
55	  private boolean isStarted;
56	
