198	  /**
199	   * Starts the animation from the first frame. Can only be called while animation is not running.
200	   */
201	  // Public API.
202	  @SuppressWarnings("unused")
203	  public void startFromFirstFrame() {
204	    Preconditions.checkArgument(!isRunning, "You cannot restart a currently running animation.");
205	    state.frameLoader.setNextStartFromFirstFrame();
206	    start();
207	  }
