209	  @Override
210	  public void start() {
211	    isStarted = true;
212	    resetLoopCount();
213	    if (isVisible) {
214	      startRunning();
215	    }
216	  }
217	
218	  @Override
219	  public void stop() {
220	    isStarted = false;
221	    stopRunning();
222	  }
223	
224	  private void startRunning() {
225	    Preconditions.checkArgument(
226	        !isRecycled,
227	        "You cannot start a recycled Drawable. Ensure that"
228	            + "you clear any references to the Drawable when clearing the corresponding request.");
229	    // If we have only a single frame, we don't want to decode it endlessly.
230	    if (state.frameLoader.getFrameCount() == 1) {
231	      invalidateSelf();
232	    } else if (!isRunning) {
233	      isRunning = true;
234	      state.frameLoader.subscribe(this);
235	      invalidateSelf();
236	    }
237	  }
238	
239	  private void stopRunning() {
240	    isRunning = false;
241	    state.frameLoader.unsubscribe(this);
242	  }
