244	  @Override
245	  public boolean setVisible(boolean visible, boolean restart) {
246	    Preconditions.checkArgument(
247	        !isRecycled,
248	        "Cannot change the visibility of a recycled resource."
249	            + " Ensure that you unset the Drawable from your View before changing the View's"
250	            + " visibility.");
251	    isVisible = visible;
252	    if (!visible) {
253	      stopRunning();
254	    } else if (isStarted) {
255	      startRunning();
256	    }
257	    return super.setVisible(visible, restart);
258	  }
