286	  @Override
287	  public void draw(@NonNull Canvas canvas) {
288	    if (isRecycled) {
289	      return;
290	    }
291	
292	    if (applyGravity) {
293	      Gravity.apply(GRAVITY, getIntrinsicWidth(), getIntrinsicHeight(), getBounds(), getDestRect());
294	      applyGravity = false;
295	    }
296	
297	    Bitmap currentFrame = state.frameLoader.getCurrentFrame();
298	    canvas.drawBitmap(currentFrame, null, getDestRect(), getPaint());
299	  }
300	
301	  @Override
302	  public void setAlpha(int i) {
303	    getPaint().setAlpha(i);
304	  }
305	
306	  @Override
