327	    // We can't tell, so default to transparent to be safe.
328	    return PixelFormat.TRANSPARENT;
329	  }
330	
331	  // See #1087.
332	  private Callback findCallback() {
333	    Callback callback = getCallback();
334	    while (callback instanceof Drawable) {
335	      callback = ((Drawable) callback).getCallback();
336	    }
337	    return callback;
338	  }
339	
340	  @Override
341	  public void onFrameReady() {
342	    if (findCallback() == null) {
343	      stop();
344	      invalidateSelf();
345	      return;
346	    }
347	
348	    invalidateSelf();
349	
350	    if (getFrameIndex() == getFrameCount() - 1) {
351	      loopCount++;
352	    }
353	
354	    if (maxLoopCount != LOOP_FOREVER && loopCount >= maxLoopCount) {
355	      stop();
356	      notifyAnimationEndToListeners();
357	    }
358	  }
359	
360	  private void notifyAnimationEndToListeners() {
361	    if (animationCallbacks != null) {
362	      for (int i = 0, size = animationCallbacks.size(); i < size; i++) {
363	        animationCallbacks.get(i).onAnimationEnd(this);
364	      }
365	    }
366	  }
367	
368	  @Override
369	  public ConstantState getConstantState() {
370	    return state;
371	  }
372	
373	  /** Clears any resources for loading frames that are currently held on to by this object. */
374	  public void recycle() {
375	    isRecycled = true;
376	    state.frameLoader.clear();
377	  }
378	
379	  // For testing.
380	  boolean isRecycled() {
381	    return isRecycled;
382	  }
383	
384	  // Public API.
385	  @SuppressWarnings("WeakerAccess")
386	  public void setLoopCount(int loopCount) {
387	    if (loopCount <= 0 && loopCount != LOOP_FOREVER && loopCount != LOOP_INTRINSIC) {
388	      throw new IllegalArgumentException(
389	          "Loop count must be greater than 0, or equal to "
390	              + "GlideDrawable.LOOP_FOREVER, or equal to GlideDrawable.LOOP_INTRINSIC");
391	    }
392	
393	    if (loopCount == LOOP_INTRINSIC) {
394	      int intrinsicCount = state.frameLoader.getLoopCount();
395	      maxLoopCount =
396	          (intrinsicCount == TOTAL_ITERATION_COUNT_FOREVER) ? LOOP_FOREVER : intrinsicCount;
397	    } else {
398	      maxLoopCount = loopCount;
399	    }
400	  }
401	
402	  /**
403	   * Register callback to listen to GifDrawable animation end event after specific loop count set by
404	   * {@link GifDrawable#setLoopCount(int)}.
405	   *
406	   * <p>Note: This will only be called if the Gif stop because it reaches the loop count. Unregister
407	   * this in onLoadCleared to avoid potential memory leak.
408	   *
409	   * @see GifDrawable#unregisterAnimationCallback(AnimationCallback).
410	   * @param animationCallback Animation callback {@link Animatable2Compat.AnimationCallback}.
411	   */
412	  @Override
413	  public void registerAnimationCallback(@NonNull AnimationCallback animationCallback) {
414	    if (animationCallback == null) {
415	      return;
416	    }
417	    if (animationCallbacks == null) {
418	      animationCallbacks = new ArrayList<>();
419	    }
420	    animationCallbacks.add(animationCallback);
421	  }
422	
423	  @Override
424	  public boolean unregisterAnimationCallback(@NonNull AnimationCallback animationCallback) {
425	    if (animationCallbacks == null || animationCallback == null) {
426	      return false;
427	    }
428	    return animationCallbacks.remove(animationCallback);
429	  }
430	
431	  @Override
432	  public void clearAnimationCallbacks() {
433	    if (animationCallbacks != null) {
434	      animationCallbacks.clear();
435	    }
436	  }
437	
438	  static final class GifState extends ConstantState {
439	    @VisibleForTesting final GifFrameLoader frameLoader;
440	
441	    GifState(GifFrameLoader frameLoader) {
442	      this.frameLoader = frameLoader;
443	    }
444	
445	    @NonNull
446	    @Override
447	    public Drawable newDrawable(Resources res) {
448	      return newDrawable();
449	    }
450	
451	    @NonNull
452	    @Override
453	    public Drawable newDrawable() {
454	      return new GifDrawable(this);
455	    }
456	
457	    @Override
458	    public int getChangingConfigurations() {
459	      return 0;
460	    }
461	  }
462	}
