3	import androidx.annotation.NonNull;
4	import com.bumptech.glide.load.Key;
5	import com.bumptech.glide.load.Options;
6	import com.bumptech.glide.load.Transformation;
7	import com.bumptech.glide.load.engine.bitmap_recycle.ArrayPool;
8	import com.bumptech.glide.util.LruCache;
9	import com.bumptech.glide.util.Util;
10	import java.nio.ByteBuffer;
11	import java.security.MessageDigest;
12	
13	/** A cache key for downsampled and transformed resource data + any requested signature. */
14	final class ResourceCacheKey implements Key {
15	  private static final LruCache<Class<?>, byte[]> RESOURCE_CLASS_BYTES = new LruCache<>(50);
16	  private final ArrayPool arrayPool;
17	  private final Key sourceKey;
18	  private final Key signature;
19	  private final int width;
20	  private final int height;
21	  private final Class<?> decodedResourceClass;
22	  private final Options options;
23	  private final Transformation<?> transformation;
24	
25	  ResourceCacheKey(
26	      ArrayPool arrayPool,
27	      Key sourceKey,
28	      Key signature,
29	      int width,
30	      int height,
31	      Transformation<?> appliedTransformation,
32	      Class<?> decodedResourceClass,
33	      Options options) {
34	    this.arrayPool = arrayPool;
35	    this.sourceKey = sourceKey;
36	    this.signature = signature;
37	    this.width = width;
38	    this.height = height;
39	    this.transformation = appliedTransformation;
40	    this.decodedResourceClass = decodedResourceClass;
41	    this.options = options;
42	  }
43	
44	  @Override
45	  public boolean equals(Object o) {
46	    if (o instanceof ResourceCacheKey) {
47	      ResourceCacheKey other = (ResourceCacheKey) o;
48	      return height == other.height
49	          && width == other.width
50	          && Util.bothNullOrEqual(transformation, other.transformation)
51	          && decodedResourceClass.equals(other.decodedResourceClass)
52	          && sourceKey.equals(other.sourceKey)
53	          && signature.equals(other.signature)
54	          && options.equals(other.options);
55	    }
56	    return false;
57	  }
58	
59	  @Override
60	  public int hashCode() {
61	    int result = sourceKey.hashCode();
62	    result = 31 * result + signature.hashCode();
63	    result = 31 * result + width;
64	    result = 31 * result + height;
65	    if (transformation != null) {
66	      result = 31 * result + transformation.hashCode();
67	    }
68	    result = 31 * result + decodedResourceClass.hashCode();
69	    result = 31 * result + options.hashCode();
70	    return result;
71	  }
72	
73	  // TODO: Include relevant options?
74	  @Override
75	  public void updateDiskCacheKey(@NonNull MessageDigest messageDigest) {
76	    byte[] dimensions = arrayPool.getExact(8, byte[].class);
77	    ByteBuffer.wrap(dimensions).putInt(width).putInt(height).array();
78	    signature.updateDiskCacheKey(messageDigest);
79	    sourceKey.updateDiskCacheKey(messageDigest);
80	    messageDigest.update(dimensions);
81	    if (transformation != null) {
82	      transformation.updateDiskCacheKey(messageDigest);
83	    }
84	    options.updateDiskCacheKey(messageDigest);
85	    messageDigest.update(getResourceClassBytes());
86	    arrayPool.put(dimensions);
87	  }
88	
89	  private byte[] getResourceClassBytes() {
90	    byte[] result = RESOURCE_CLASS_BYTES.get(decodedResourceClass);
91	    if (result == null) {
92	      result = decodedResourceClass.getName().getBytes(CHARSET);
93	      RESOURCE_CLASS_BYTES.put(decodedResourceClass, result);
94	    }
95	    return result;
96	  }
97	
98	  @Override
99	  public String toString() {
100	    return "ResourceCacheKey{"
101	        + "sourceKey="
102	        + sourceKey
103	        + ", signature="
104	        + signature
105	        + ", width="
106	        + width
107	        + ", height="
108	        + height
109	        + ", decodedResourceClass="
110	        + decodedResourceClass
111	        + ", transformation='"
112	        + transformation
113	        + '\''
114	        + ", options="
115	        + options
116	        + '}';
117	  }
118	}
