3	import androidx.annotation.GuardedBy;
4	import androidx.annotation.Nullable;
5	
6	/**
7	 * A coordinator that coordinates two individual {@link Request}s that load a small thumbnail
8	 * version of an image and the full size version of the image at the same time.
9	 */
10	public class ThumbnailRequestCoordinator implements RequestCoordinator, Request {
11	  @Nullable private final RequestCoordinator parent;
12	  private final Object requestLock;
13	
14	  private volatile Request full;
15	  private volatile Request thumb;
16	
17	  @GuardedBy("requestLock")
18	  private RequestState fullState = RequestState.CLEARED;
19	
20	  @GuardedBy("requestLock")
21	  private RequestState thumbState = RequestState.CLEARED;
22	
23	  // Only used to check if the full request is cleared by the thumbnail request.
24	  @GuardedBy("requestLock")
25	  private boolean isRunningDuringBegin;
26	
27	  public ThumbnailRequestCoordinator(Object requestLock, @Nullable RequestCoordinator parent) {
28	    this.requestLock = requestLock;
29	    this.parent = parent;
30	  }
31	
32	  public void setRequests(Request full, Request thumb) {
33	    this.full = full;
34	    this.thumb = thumb;
35	  }
36	
37	  /**
38	   * Returns true if the request is either the request loading the full size image or if the request
39	   * loading the full size image has not yet completed.
40	   *
41	   * @param request {@inheritDoc}
42	   */
43	  @Override
44	  public boolean canSetImage(Request request) {
45	    synchronized (requestLock) {
46	      return parentCanSetImage() && (request.equals(full) || fullState != RequestState.SUCCESS);
47	    }
48	  }
49	
50	  @GuardedBy("requestLock")
51	  private boolean parentCanSetImage() {
52	    return parent == null || parent.canSetImage(this);
53	  }
54	
55	  /**
56	   * Returns true if the request is the request loading the full size image and if neither the full
57	   * nor the thumbnail image have completed successfully.
58	   *
59	   * @param request {@inheritDoc}.
60	   */
61	  @Override
62	  public boolean canNotifyStatusChanged(Request request) {
63	    synchronized (requestLock) {
64	      return parentCanNotifyStatusChanged() && request.equals(full) && !isAnyResourceSet();
65	    }
66	  }
67	
68	  @Override
69	  public boolean canNotifyCleared(Request request) {
70	    synchronized (requestLock) {
71	      return parentCanNotifyCleared() && request.equals(full) && fullState != RequestState.PAUSED;
72	    }
73	  }
74	
75	  @GuardedBy("requestLock")
76	  private boolean parentCanNotifyCleared() {
77	    return parent == null || parent.canNotifyCleared(this);
78	  }
79	
80	  @GuardedBy("requestLock")
81	  private boolean parentCanNotifyStatusChanged() {
82	    return parent == null || parent.canNotifyStatusChanged(this);
83	  }
84	
85	  @Override
86	  public boolean isAnyResourceSet() {
87	    synchronized (requestLock) {
88	      return thumb.isAnyResourceSet() || full.isAnyResourceSet();
89	    }
90	  }
91	
92	  @Override
93	  public void onRequestSuccess(Request request) {
94	    synchronized (requestLock) {
95	      if (request.equals(thumb)) {
96	        thumbState = RequestState.SUCCESS;
97	        return;
98	      }
99	      fullState = RequestState.SUCCESS;
100	      if (parent != null) {
101	        parent.onRequestSuccess(this);
102	      }
103	      // Clearing the thumb is not necessarily safe if the thumb is being displayed in the Target,
104	      // as a layer in a cross fade for example. The only way we know the thumb is not being
105	      // displayed and is therefore safe to clear is if the thumb request has not yet completed.
106	      if (!thumbState.isComplete()) {
107	        thumb.clear();
108	      }
109	    }
110	  }
111	
112	  @Override
113	  public void onRequestFailed(Request request) {
114	    synchronized (requestLock) {
115	      if (!request.equals(full)) {
116	        thumbState = RequestState.FAILED;
117	        return;
118	      }
119	      fullState = RequestState.FAILED;
120	
121	      if (parent != null) {
122	        parent.onRequestFailed(this);
123	      }
124	    }
125	  }
126	
127	  @Override
128	  public RequestCoordinator getRoot() {
129	    synchronized (requestLock) {
130	      return parent != null ? parent.getRoot() : this;
131	    }
132	  }
133	
134	  /** Starts first the thumb request and then the full request. */
135	  @Override
136	  public void begin() {
137	    synchronized (requestLock) {
138	      isRunningDuringBegin = true;
139	      try {
140	        // If the request has completed previously, there's no need to restart both the full and the
141	        // thumb, we can just restart the full.
142	        if (fullState != RequestState.SUCCESS && thumbState != RequestState.RUNNING) {
143	          thumbState = RequestState.RUNNING;
144	          thumb.begin();
145	        }
146	        if (isRunningDuringBegin && fullState != RequestState.RUNNING) {
147	          fullState = RequestState.RUNNING;
148	          full.begin();
149	        }
150	      } finally {
151	        isRunningDuringBegin = false;
152	      }
153	    }
154	  }
155	
156	  @Override
157	  public void clear() {
158	    synchronized (requestLock) {
159	      isRunningDuringBegin = false;
160	      fullState = RequestState.CLEARED;
161	      thumbState = RequestState.CLEARED;
162	      thumb.clear();
163	      full.clear();
164	    }
165	  }
166	
167	  @Override
168	  public void pause() {
169	    synchronized (requestLock) {
170	      if (!thumbState.isComplete()) {
171	        thumbState = RequestState.PAUSED;
172	        thumb.pause();
173	      }
174	      if (!fullState.isComplete()) {
175	        fullState = RequestState.PAUSED;
176	        full.pause();
177	      }
178	    }
179	  }
180	
181	  @Override
182	  public boolean isRunning() {
183	    synchronized (requestLock) {
184	      return fullState == RequestState.RUNNING;
185	    }
186	  }
187	
188	  @Override
189	  public boolean isComplete() {
190	    synchronized (requestLock) {
191	      return fullState == RequestState.SUCCESS;
192	    }
193	  }
194	
195	  @Override
196	  public boolean isCleared() {
197	    synchronized (requestLock) {
198	      return fullState == RequestState.CLEARED;
199	    }
200	  }
201	
202	  @Override
203	  public boolean isEquivalentTo(Request o) {
204	    if (o instanceof ThumbnailRequestCoordinator) {
205	      ThumbnailRequestCoordinator that = (ThumbnailRequestCoordinator) o;
206	      return (full == null ? that.full == null : full.isEquivalentTo(that.full))
207	          && (thumb == null ? that.thumb == null : thumb.isEquivalentTo(that.thumb));
