395	  private static final class DefaultThreadFactory implements ThreadFactory {
396	
397	    private final ThreadFactory delegate;
398	    private final String name;
399	    @Synthetic final UncaughtThrowableStrategy uncaughtThrowableStrategy;
400	    @Synthetic final boolean preventNetworkOperations;
401	    private final AtomicInteger threadNum = new AtomicInteger();
402	
403	    DefaultThreadFactory(
404	        ThreadFactory delegate,
405	        String name,
406	        UncaughtThrowableStrategy uncaughtThrowableStrategy,
407	        boolean preventNetworkOperations) {
408	      this.delegate = delegate;
409	      this.name = name;
410	      this.uncaughtThrowableStrategy = uncaughtThrowableStrategy;
411	      this.preventNetworkOperations = preventNetworkOperations;
412	    }
413	
414	    @Override
415	    public Thread newThread(@NonNull final Runnable runnable) {
416	      Thread newThread =
417	          delegate.newThread(
418	              new Runnable() {
419	                @Override
420	                public void run() {
421	                  if (preventNetworkOperations) {
422	                    StrictMode.setThreadPolicy(
423	                        new ThreadPolicy.Builder().detectNetwork().penaltyDeath().build());
424	                  }
425	                  try {
426	                    runnable.run();
427	                  } catch (Throwable t) {
428	                    uncaughtThrowableStrategy.handle(t);
429	                  }
430	                }
431	              });
432	      newThread.setName("glide-" + name + "-thread-" + threadNum.getAndIncrement());
433	      return newThread;
434	    }
435	  }
