542	    /** Builds a new {@link GlideExecutor} with any previously specified options. */
543	    public GlideExecutor build() {
544	      if (TextUtils.isEmpty(name)) {
545	        throw new IllegalArgumentException(
546	            "Name must be non-null and non-empty, but given: " + name);
547	      }
548	      ThreadFactory factory =
549	          new DefaultThreadFactory(
550	              threadFactory, name, uncaughtThrowableStrategy, preventNetworkOperations);
551	      BlockingQueue<Runnable> queue =
552	          isUnlimited ? new SynchronousQueue<>() : new PriorityBlockingQueue<>();
553	      ThreadPoolExecutor executor;
554	      if (onExecuteDecorator != null) {
555	        executor =
556	            new ThreadPoolExecutor(
557	                corePoolSize,
558	                maximumPoolSize,
559	                /* keepAliveTime= */ threadTimeoutMillis,
560	                TimeUnit.MILLISECONDS,
561	                queue,
562	                factory) {
563	              @Override
564	              public void execute(@NonNull Runnable command) {
565	                super.execute(onExecuteDecorator.apply(command));
566	              }
567	            };
568	      } else {
569	        executor =
570	            new ThreadPoolExecutor(
571	                corePoolSize,
572	                maximumPoolSize,
573	                /* keepAliveTime= */ threadTimeoutMillis,
574	                TimeUnit.MILLISECONDS,
575	                queue,
576	                factory);
577	      }
578	
579	      if (threadTimeoutMillis != NO_THREAD_TIMEOUT) {
580	        executor.allowCoreThreadTimeOut(true);
581	      }
582	
583	      return new GlideExecutor(executor);
