12	import java.io.ByteArrayOutputStream;
13	import java.io.IOException;
14	import java.io.InputStream;
15	import java.nio.ByteBuffer;
16	import java.util.List;
17	
18	/**
19	 * A relatively inefficient decoder for {@link com.bumptech.glide.load.resource.gif.GifDrawable}
20	 * that converts {@link java.io.InputStream}s to {@link java.nio.ByteBuffer}s and then passes the
21	 * buffer to a wrapped decoder.
22	 */
23	public class StreamGifDecoder implements ResourceDecoder<InputStream, GifDrawable> {
24	  private static final String TAG = "StreamGifDecoder";
25	
26	  private final List<ImageHeaderParser> parsers;
27	  private final ResourceDecoder<ByteBuffer, GifDrawable> byteBufferDecoder;
28	  private final ArrayPool byteArrayPool;
29	
30	  public StreamGifDecoder(
31	      List<ImageHeaderParser> parsers,
32	      ResourceDecoder<ByteBuffer, GifDrawable> byteBufferDecoder,
33	      ArrayPool byteArrayPool) {
34	    this.parsers = parsers;
35	    this.byteBufferDecoder = byteBufferDecoder;
36	    this.byteArrayPool = byteArrayPool;
37	  }
38	
39	  @Override
40	  public boolean handles(@NonNull InputStream source, @NonNull Options options) throws IOException {
41	    return !options.get(GifOptions.DISABLE_ANIMATION)
42	        && ImageHeaderParserUtils.getType(parsers, source, byteArrayPool) == ImageType.GIF;
43	  }
44	
45	  @Override
46	  public Resource<GifDrawable> decode(
47	      @NonNull InputStream source, int width, int height, @NonNull Options options)
48	      throws IOException {
49	    byte[] data = inputStreamToBytes(source);
50	    if (data == null) {
51	      return null;
52	    }
53	    ByteBuffer byteBuffer = ByteBuffer.wrap(data);
54	    return byteBufferDecoder.decode(byteBuffer, width, height, options);
55	  }
56	
57	  private static byte[] inputStreamToBytes(InputStream is) {
58	    final int bufferSize = 16384;
59	    ByteArrayOutputStream buffer = new ByteArrayOutputStream(bufferSize);
60	    try {
61	      int nRead;
62	      byte[] data = new byte[bufferSize];
63	      while ((nRead = is.read(data)) != -1) {
64	        buffer.write(data, 0, nRead);
65	      }
66	      buffer.flush();
67	    } catch (IOException e) {
68	      if (Log.isLoggable(TAG, Log.WARN)) {
69	        Log.w(TAG, "Error reading data from stream", e);
70	      }
71	      return null;
72	    }
73	    return buffer.toByteArray();
74	  }
75	}
