142	      Log.v(
143	          TAG,
144	          "Downsampling GIF"
145	              + ", sampleSize: "
146	              + sampleSize
147	              + ", target dimens: ["
148	              + targetWidth
149	              + "x"
150	              + targetHeight
151	              + "]"
152	              + ", actual dimens: ["
153	              + gifHeader.getWidth()
154	              + "x"
155	              + gifHeader.getHeight()
156	              + "]");
157	    }
158	    return sampleSize;
159	  }
