61	
62	  @Override
63	  public void put(Bitmap bitmap) {
64	    int size = Util.getBitmapByteSize(bitmap);
65	    Key key = keyPool.get(size, bitmap.getConfig());
66	
67	    groupedMap.put(key, bitmap);
68	
69	    NavigableMap<Integer, Integer> sizes = getSizesForConfig(bitmap.getConfig());
70	    Integer current = sizes.get(key.size);
71	    sizes.put(key.size, current == null ? 1 : current + 1);
