73	
74	  @Override
75	  @Nullable
76	  public Bitmap get(int width, int height, Bitmap.Config config) {
77	    int size = Util.getBitmapByteSize(width, height, config);
78	    Key bestKey = findBestKey(size, config);
79	
80	    Bitmap result = groupedMap.get(bestKey);
81	    if (result != null) {
82	      // Decrement must be called before reconfigure.
83	      decrementBitmapOfSize(bestKey.size, result);
