256	   *
257	   * @param buffer the byte array in which to store the bytes read.
258	   * @return the number of bytes actually read or -1 if end of stream.
259	   * @throws IndexOutOfBoundsException if {@code offset < 0} or {@code byteCount < 0}, or if {@code
260	   *     offset + byteCount} is greater than the size of {@code buffer}.
261	   * @throws IOException if the stream is already closed or another IOException occurs.
262	   */
263	  @Override
264	  public synchronized int read(@NonNull byte[] buffer, int offset, int byteCount)
265	      throws IOException {
266	    // Use local ref since buf may be invalidated by an unsynchronized close()
267	    byte[] localBuf = buf;
268	    if (localBuf == null) {
269	      throw streamClosed();
270	    }
271	    // Arrays.checkOffsetAndCount(buffer.length, offset, byteCount);
272	    if (byteCount == 0) {
273	      return 0;
274	    }
275	    InputStream localIn = in;
276	    if (localIn == null) {
277	      throw streamClosed();
278	    }
279	
280	    int required;
281	    if (pos < count) {
282	      // There are bytes available in the buffer.
283	      int copylength = count - pos >= byteCount ? byteCount : count - pos;
284	      System.arraycopy(localBuf, pos, buffer, offset, copylength);
285	      pos += copylength;
286	      if (copylength == byteCount || localIn.available() == 0) {
287	        return copylength;
288	      }
289	      offset += copylength;
290	      required = byteCount - copylength;
291	    } else {
292	      required = byteCount;
293	    }
294	
295	    while (true) {
296	      int read;
297	      // If we're not marked and the required size is greater than the buffer,
298	      // simply read the bytes directly bypassing the buffer.
299	      if (markpos == -1 && required >= localBuf.length) {
300	        read = localIn.read(buffer, offset, required);
301	        if (read == -1) {
302	          return required == byteCount ? -1 : byteCount - required;
303	        }
304	      } else {
305	        if (fillbuf(localIn, localBuf) == -1) {
306	          return required == byteCount ? -1 : byteCount - required;
307	        }
308	        // localBuf may have been invalidated by fillbuf
309	        if (localBuf != buf) {
310	          localBuf = buf;
311	          if (localBuf == null) {
312	            throw streamClosed();
313	          }
314	        }
315	
316	        read = count - pos >= required ? required : count - pos;
317	        System.arraycopy(localBuf, pos, buffer, offset, read);
318	        pos += read;
319	      }
320	      required -= read;
321	      if (required == 0) {
322	        return byteCount;
323	      }
324	      if (localIn.available() == 0) {
325	        return byteCount - required;
326	      }
327	      offset += read;
328	    }
329	  }
