331	  /**
332	   * Resets this stream to the last marked location.
333	   *
334	   * @throws IOException if this stream is closed, no mark has been put or the mark is no longer
335	   *     valid because more than {@code readlimit} bytes have been read since setting the mark.
336	   * @see #mark(int)
337	   */
338	  @Override
339	  public synchronized void reset() throws IOException {
340	    if (buf == null) {
341	      throw new IOException("Stream is closed");
342	    }
343	    if (-1 == markpos) {
344	      throw new InvalidMarkException(
345	          "Mark has been invalidated, pos: " + pos + " markLimit: " + marklimit);
346	    }
347	    pos = markpos;
348	  }
