350	  /**
351	   * Skips {@code byteCount} bytes in this stream. Subsequent calls to {@link #read} will not return
352	   * these bytes unless {@link #reset} is used.
353	   *
354	   * @param byteCount the number of bytes to skip. This method does nothing and returns 0 if {@code
355	   *     byteCount} is less than zero.
356	   * @return the number of bytes actually skipped.
357	   * @throws IOException if this stream is closed or another IOException occurs.
358	   */
359	  @Override
360	  public synchronized long skip(long byteCount) throws IOException {
361	    if (byteCount < 1) {
362	      return 0;
363	    }
364	    // Use local refs since buf and in may be invalidated by an unsynchronized close()
365	    byte[] localBuf = buf;
366	    if (localBuf == null) {
367	      throw streamClosed();
368	    }
369	    InputStream localIn = in;
370	    if (localIn == null) {
371	      throw streamClosed();
372	    }
373	
374	    if (count - pos >= byteCount) {
375	      pos = (int) (pos + byteCount);
376	      return byteCount;
377	    }
378	    // See https://errorprone.info/bugpattern/IntLongMath.
379	    long read = (long) count - pos;
380	    pos = count;
381	
382	    if (markpos != -1 && byteCount <= marklimit) {
383	      if (fillbuf(localIn, localBuf) == -1) {
384	        return read;
385	      }
386	      if (count - pos >= byteCount - read) {
387	        // See https://errorprone.info/bugpattern/NarrowingCompoundAssignment.
388	        pos = (int) (pos + byteCount - read);
389	        return byteCount;
390	      }
391	      // Couldn't get all the bytes, skip what we read.
392	      read = read + count - pos;
393	      pos = count;
394	      return read;
395	    }
396	
397	    // We can't skip over the remaining bytes without exceeding the mark limit so there will be no
398	    // way to reset to a proper position in the stream.
399	    long skipped = localIn.skip(byteCount - read);
400	    if (skipped > 0) {
401	      markpos = -1;
402	    }
403	    return read + skipped;
404	  }
