408	   * smaller than the amount of data read after the mark position.
409	   */
410	  static class InvalidMarkException extends IOException {
411	    private static final long serialVersionUID = -4338378848813561757L;
412	
413	    InvalidMarkException(String detailMessage) {
414	      super(detailMessage);
415	    }
416	  }
